WITH valid AS (SELECT id, product_id, quantity, last_restock, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE store_id IN (2, 3, 4)), ranked AS (SELECT * FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC NULLS FIRST, id) = 1), enriched AS (SELECT *, SUM(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, LAG(quantity, 1, 0) OVER w_hist AS prev_quantity, SUM(quantity) OVER (ORDER BY days_since_last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity FROM ranked WINDOW w_hist AS (PARTITION BY product_id ORDER BY quantity, id)), with_windows AS (SELECT id, product_id, quantity, last_restock, days_since_last_restock, running_quantity, prev_quantity, cumulative_quantity, AVG(quantity) OVER (ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS quantity_avg_2, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY prev_quantity DESC NULLS FIRST) AS prev_quantity_dense_rank FROM enriched), cleaned AS (SELECT id, product_id, quantity, last_restock, days_since_last_restock, cumulative_quantity, prev_quantity_dense_rank, FLOOR(prev_quantity_dense_rank) AS prev_quantity_dense_rank_whole, CASE WHEN quantity >= 257 THEN 'High' WHEN quantity >= 70 THEN 'Medium' ELSE 'Low' END AS quantity_tier FROM with_windows WHERE last_restock > DATE '2024-02-19'), deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY product_id ORDER BY prev_quantity_dense_rank DESC NULLS LAST) AS latest_rank FROM cleaned) t WHERE latest_rank = 1), base AS (SELECT id, product_id, last_restock, days_since_last_restock, cumulative_quantity, prev_quantity_dense_rank, prev_quantity_dense_rank_whole, latest_rank, days_since_last_restock - quantity AS days_since_last_restock_minus_quantity FROM deduped WHERE last_restock > DATE '2023-07-27'), summary AS (SELECT product_id, COUNT(*) AS cnt, COUNT(*) AS event_count, SUM(prev_quantity_dense_rank_whole) AS total_prev_quantity_dense_rank_whole FROM base GROUP BY product_id HAVING COUNT(*) < 1) SELECT s.product_id, s.cnt, (SELECT AVG(s2.revenue) FROM store_sales s2 WHERE s2.product_id = s.product_id) AS avg_store_sale_revenue FROM summary s;
